<template>
  <article class="fire-record-evidence"><header class="evidence-heading"><span class="point-state checked">已完成点检</span><el-tag :type="record.result==='normal'?'success':'danger'">检查结果：{{ f.resultName(record.result) }}</el-tag></header><dl class="evidence-meta"><div><dt>点检人</dt><dd>{{ record.actorName || '—' }}</dd></div><div><dt>{{ recognition?'拍照登记时间（系统）':'点检时间' }}</dt><dd>{{ f.time(record.actualCheckedAt || record.submittedAt) }}</dd></div><div><dt>点位</dt><dd>{{ record.pointSnapshot?.code }} · {{ record.pointSnapshot?.areaName }}</dd></div><div><dt>位置</dt><dd>{{ record.pointSnapshot?.location || record.pointSnapshot?.name || '—' }}</dd></div></dl><p v-if="record.backfillReason" class="fire-note">提交于 {{ f.time(record.submittedAt) }} · 补录原因：{{ record.backfillReason }}</p><p v-if="record.remark">{{ record.remark }}</p><div v-for="item in record.items || []" :key="item.assetId" class="record-item"><strong>{{ item.assetSnapshot?.code || item.assetSnapshot?.name || '器材' }}</strong><span :class="item.result==='normal'?'checked-text':'danger'">{{ f.resultName(item.result) }}</span><span>{{ item.remark }}</span></div><section v-if="recognition" class="recognition-evidence"><h4>AI 识别凭证</h4><p>设备编码 {{ recognition.deviceCode }} · 所属月份 {{ recognition.inspectionMonth || (recognition.year && recognition.month ? recognition.year+'-'+String(recognition.month).padStart(2,'0') : '—') }}</p><div v-for="(check,index) in recognition.checks || []" :key="index" class="record-item"><span>{{ check.name }}</span><strong :class="check.result==='normal'?'checked-text':'danger'">{{ check.mark || f.resultName(check.result) }}</strong><small v-if="check.source==='manual_confirmation'" class="fire-note">人工确认</small></div><p v-if="recognition.confirmation" class="fire-note">编号与位置已经人工核对<span v-if="recognition.confirmation.originalDeviceCode!==recognition.deviceCode"> · 原识别编号 {{ recognition.confirmation.originalDeviceCode || '未识别' }}</span><span v-if="recognition.confirmation.ledgerLocation!==recognition.location"> · 台账位置 {{ recognition.confirmation.ledgerLocation }}</span></p><p class="fire-note">识别时间 {{ f.time(recognition.recognizedAt) }}</p></section><div class="fire-photo-grid"><FirePreviewImage v-for="photo in record.photos || []" :key="photo.id" class="history-photo" :src="f.photoUrls[photo.id]" :preview-src-list="(record.photos || []).map(p=>f.photoUrls[p.id]).filter(Boolean)" fit="cover"><template #error><button class="photo-retry" type="button" @click="f.loadPhoto(photo)">重新加载照片</button></template></FirePreviewImage></div></article>
</template>
<script setup>
import FirePreviewImage from './FirePreviewImage.vue'
import { computed, inject } from 'vue'
const props=defineProps({record:{type:Object,required:true}}),f=inject('fireInspection')
const recognition=computed(()=>props.record.pointSnapshot?.recognition || props.record.recognition)
</script>
